package in.paisa.personal;
import org.json.*;
public final class CaptureMatcher {
 private static boolean incoming(String kind){return kind.equals("income")||kind.equals("borrow")||kind.equals("receive")||kind.equals("refund");}
 public static boolean sameReference(SmsParser.Parsed p,JSONObject old){if(p.reference.isEmpty()||!p.reference.equals(old.optString("reference"))||p.amount!=old.optLong("amount"))return false;boolean in=incoming(p.kind);String oldKind=old.optString("kind");if(in!=incoming(oldKind)&&!oldKind.equals("transfer"))return false;if(oldKind.equals("transfer")&&in&&!old.optString("toAccountId").isEmpty()&&!old.optString("toAccountId").endsWith(":unknown")&&!p.accountId.endsWith(":unknown")&&!p.accountId.equals("bank:default"))return old.optString("toAccountId").equals(p.accountId);String bank=old.optString("bank");if(!bank.isEmpty()&&!bank.equals("Bank")&&!p.bank.equals("Bank")&&!p.bank.equals(bank))return false;String before=old.optString(oldKind.equals("transfer")&&in?"toAccountId":"accountId"),after=p.accountId;String a=before.substring(before.lastIndexOf(':')+1),b=after.substring(after.lastIndexOf(':')+1);if(a.matches("\\d{4}")&&b.matches("\\d{4}")&&(before.startsWith("credit:")!=after.startsWith("credit:")))return false;return !a.matches("\\d{4}")||!b.matches("\\d{4}")||a.equals(b);}
 public static boolean possible(SmsParser.Parsed p,JSONObject old,long date,String source){if(old.optBoolean("deleted")||!old.optString("duplicateOf").isEmpty()||p.amount!=old.optLong("amount")||!p.kind.equals(old.optString("kind"))||Math.abs(date-old.optLong("date"))>=180000||source.equals(old.optString("source")))return false;return !p.merchantKey.isEmpty()&&p.merchantKey.equals(old.optString("merchantKey"))||p.title.equalsIgnoreCase(old.optString("title"))||old.optString("source").equals("Manual")&&p.accountId.equals(old.optString("accountId"));}
 public static boolean possible(SmsParser.Parsed p,JSONObject old,long date,String source,String pkg){if(!source.equals("SMS")&&source.equals(old.optString("source"))&&!pkg.equals(old.optString("sourcePackage"))){try{JSONObject other=new JSONObject(old.toString()).put("source","Different selected app");return possible(p,other,date,source);}catch(JSONException e){return false;}}return possible(p,old,date,source);}
}
